js=r'''
var L=LAB,$=L.$;
function corr(){var cv=$('#corrCv');if(!cv)return;var F=L.fit(cv),c=F.c,W=F.W,H=F.H;c.clearRect(0,0,W,H);var D=[['평균온도',-0.867],['충전률',-0.316],['방전깊이',-0.172],['보관SOC',-0.057]],Lm=80,R=20,cx=W-R,x0=Lm,X=function(v){return x0+(v+1)*(cx-x0);};
 c.font='13px '+getComputedStyle(document.body).fontFamily;c.strokeStyle='#9aa5b1';c.beginPath();c.moveTo(X(0),6);c.lineTo(X(0),H-20);c.stroke();c.fillStyle='#5b6874';c.textAlign='center';[-1,-0.5,0].forEach(function(v){c.fillText(v,X(v),H-4);});
 D.forEach(function(d,i){var y=12+i*((H-30)/4);c.fillStyle='#1e55c8';c.fillRect(X(d[1]),y,X(0)-X(d[1]),22);c.fillStyle='#16212b';c.textAlign='right';c.fillText(d[0],Lm-6,y+16);c.textAlign='right';c.fillText(d[1].toFixed(3),X(d[1])-4,y+16);});}
corr();window.addEventListener('resize',corr);
var B0=[4,-3,2.5,0.8,-0.5];
function lam(){var l=+$('#lamR').value;$('#lamV').textContent=l.toFixed(1);var cv=$('#lamCv'),F=L.fit(cv),c=F.c,W=F.W,H=F.H;c.clearRect(0,0,W,H);
 var rid=B0.map(function(b){return b/(1+l);}),las=B0.map(function(b){var s=Math.abs(b)-l/2;return s>0?Math.sign(b)*s:0;}),Y=function(v){return H/2-v*(H/2-16)/4.5;},bw=(W-60)/B0.length;
 c.strokeStyle='#9aa5b1';c.beginPath();c.moveTo(40,Y(0));c.lineTo(W-10,Y(0));c.stroke();c.font='12px '+getComputedStyle(document.body).fontFamily;
 B0.forEach(function(b,i){var x=48+i*bw;c.fillStyle='#d5dbe2';c.fillRect(x,Math.min(Y(b),Y(0)),bw*.25,Math.abs(Y(b)-Y(0)));c.fillStyle='#1e55c8';c.fillRect(x+bw*.28,Math.min(Y(rid[i]),Y(0)),bw*.25,Math.abs(Y(rid[i])-Y(0)));c.fillStyle='#a35c00';c.fillRect(x+bw*.56,Math.min(Y(las[i]),Y(0)),bw*.25,Math.max(1,Math.abs(Y(las[i])-Y(0))));c.fillStyle='#16212b';c.textAlign='center';c.fillText('계수'+(i+1),x+bw*.4,H-4);});
 c.textAlign='left';c.fillStyle='#9aa5b1';c.fillText('■ 원래',44,14);c.fillStyle='#1e55c8';c.fillText('■ Ridge',96,14);c.fillStyle='#a35c00';c.fillText('■ Lasso',156,14);
 var z=las.filter(function(v){return v===0;}).length;$('#lamOut').innerHTML='λ = '+l.toFixed(1)+' → Ridge 계수 '+rid.map(function(v){return v.toFixed(2);}).join(' · ')+' / Lasso 계수 '+las.map(function(v){return v.toFixed(2);}).join(' · ')+' → Lasso가 0으로 만든 계수 <b>'+z+'개</b>';}
$('#lamR').oninput=lam;lam();window.addEventListener('resize',lam);
'''
